1	import React, {
2	  useCallback,
3	  useEffect,
4	  useMemo,
5	  useRef,
6	  useState,
7	} from "react";
8	import { Spinner, Text as ADSText, Tooltip } from "@appsmith/ads";
9	import { useEventCallback, useEventListener } from "usehooks-ts";
10	import { usePrevious } from "@mantine/hooks";
11	import { useNameEditor } from "./useNameEditor";
12	import styled from "styled-components";
13	
14	interface EditableTextProps {
15	  name: string;
16	  /** isLoading true will show a spinner **/
17	  isLoading?: boolean;
18	  /** if a valid name is entered, the onNameSave
19	   * will be called with the new name */
20	  onNameSave: (name: string) => void;
21	  /** Used in conjunction with exit editing to control
22	   *  this component input editable state  */
23	  isEditing: boolean;
24	  /** Used in conjunction with exit editing to control this component
25	   *  input editable state This function will be called when the
26	   *  user is trying to exit the editing mode **/
27	  exitEditing: () => void;
28	  /** Icon is replaced by spinner when isLoading is shown */
29	  icon: React.ReactNode;
30	  inputTestId?: string;
31	}
32	
33	export const Text = styled(ADSText)`
34	  min-width: 3ch;
35	`;
36	
37	export const EditableName = ({
38	  exitEditing,
39	  icon,
40	  inputTestId,
41	  isEditing,
42	  isLoading = false,
43	  name,
44	  onNameSave,
45	}: EditableTextProps) => {
46	  const previousName = usePrevious(name);
47	  const [editableName, setEditableName] = useState(name);
48	  const [validationError, setValidationError] = useState<string | null>(null);
49	  const inputRef = useRef<HTMLInputElement>(null);
50	
51	  const { normalizeName, validateName } = useNameEditor({
52	    entityName: name,
53	  });
54	
55	  const exitWithoutSaving = useCallback(() => {
56	    exitEditing();
57	    setEditableName(name);
58	    setValidationError(null);
59	  }, [exitEditing, name]);
60	
61	  const validate = useCallback(
62	    (name: string) => {
63	      const nameError = validateName(name);
64	
65	      if (nameError === null) {
66	        setValidationError(null);
67	      } else {
68	        setValidationError(nameError);
69	      }
70	
71	      return nameError;
72	    },
73	    [validateName],
74	  );
75	
76	  const attemptSave = useCallback(() => {
77	    const nameError = validate(editableName);
78	
79	    if (editableName === name) {
80	      // No change detected
81	      exitWithoutSaving();
82	    } else if (nameError === null) {
83	      // Save the new name
84	      exitEditing();
85	      onNameSave(editableName);
86	    } else {
87	      // Exit edit mode and revert name
88	      exitWithoutSaving();
89	    }
90	  }, [
91	    editableName,
92	    exitEditing,
93	    exitWithoutSaving,
94	    name,
95	    onNameSave,
96	    validate,
97	  ]);
98	
99	  const handleKeyUp = useEventCallback(
100	    (e: React.KeyboardEvent<HTMLInputElement>) => {
101	      if (e.key === "Enter") {
102	        attemptSave();
103	      } else if (e.key === "Escape") {
104	        exitWithoutSaving();
105	      }
106	    },
107	  );
108	
109	  const handleTitleChange = useEventCallback(
110	    (e: React.ChangeEvent<HTMLInputElement>) => {
111	      const value = normalizeName(e.target.value);
112	
113	      setEditableName(value);
114	      validate(value);
115	    },
116	  );
117	
118	  const inputProps = useMemo(
119	    () => ({
120	      ["data-testid"]: inputTestId,
121	      onKeyUp: handleKeyUp,
122	      onChange: handleTitleChange,
123	      autoFocus: true,
124	      style: { paddingTop: 0, paddingBottom: 0, left: -1, top: -1 },
125	    }),
126	    [handleKeyUp, handleTitleChange, inputTestId],
127	  );
128	
129	  useEventListener(
130	    "focusout",
131	    function handleFocusOut() {
132	      const input = inputRef.current;
133	
134	      if (input) {
135	        attemptSave();
136	      }
137	    },
138	    inputRef,
139	  );
140	
141	  useEffect(
142	    function syncEditableTitle() {
143	      if (!isEditing && previousName !== name) {
144	        setEditableName(name);
145	      }
146	    },
147	    [name, previousName, isEditing],
148	  );
149	
150	  // TODO: This is a temporary fix to focus the input after context retention applies focus to its target
151	  // this is a nasty hack to re-focus the input after context retention applies focus to its target
152	  // this will be addressed in a future task, likely by a focus retention modification
153	  useEffect(
154	    function recaptureFocusInEventOfFocusRetention() {
155	      const input = inputRef.current;
156	
157	      if (isEditing && input) {
158	        setTimeout(() => {
159	          input.focus();
160	        }, 200);
161	      }
162	    },
163	    [isEditing],
164	  );
165	
166	  return (
167	    <>
168	      {isLoading ? <Spinner size="sm" /> : icon}
169	      <Tooltip content={validationError} visible={Boolean(validationError)}>
170	        <Text
171	          inputProps={inputProps}
172	          inputRef={inputRef}
173	          isEditable={isEditing}
174	          kind="body-s"
175	        >
176	          {editableName}
177	        </Text>
178	      </Tooltip>
179	    </>
180	  );
181	};
