2	  ACTION_INVALID_NAME_ERROR,
3	  ACTION_NAME_CONFLICT_ERROR,
4	  createMessage,
5	} from "ee/constants/messages";
6	import { shallowEqual, useSelector } from "react-redux";
7	import type { AppState } from "ee/reducers";
8	import { getUsedActionNames } from "selectors/actionSelectors";
9	import { isNameValid, removeSpecialChars } from "utils/helpers";
10	import { useCallback } from "react";
11	
12	interface UseNameEditorProps {
13	  entityName: string;
14	  nameErrorMessage?: (name: string) => string;
15	}
16	
17	/**
18	 * Provides a unified way to validate and save entity names.
19	 */
20	export function useNameEditor(props: UseNameEditorProps) {
21	  const { entityName, nameErrorMessage = ACTION_NAME_CONFLICT_ERROR } = props;
22	
23	  const usedEntityNames = useSelector(
24	    (state: AppState) => getUsedActionNames(state, ""),
25	    shallowEqual,
26	  );
27	
28	  const validateName = useCallback(
29	    (name: string): string | null => {
30	      if (!name || name.trim().length === 0) {
31	        return createMessage(ACTION_INVALID_NAME_ERROR);
32	      } else if (name !== entityName && !isNameValid(name, usedEntityNames)) {
33	        return createMessage(nameErrorMessage, name);
34	      }
35	
36	      return null;
37	    },
38	    [entityName, nameErrorMessage, usedEntityNames],
39	  );
40	
41	  return {
42	    validateName,
43	    normalizeName: removeSpecialChars,
44	  };
45	}
