/**
 * Return type of the {@link useEditableText} hook.
 *
 * A tuple containing everything a component needs to render an inline
 * editable text field:
 * - the ref to attach to the input element
 * - the current editable value
 * - the current validation error (if any)
 * - the key up handler (Enter / Escape)
 * - the change handler
 */
export type UseEditableTextReturn = [
  React.RefObject<HTMLInputElement>,
  string,
  string | null,
  (event: React.KeyboardEvent<HTMLInputElement>) => void,
  (event: React.ChangeEvent<HTMLInputElement>) => void,
];

/**
 * A reusable hook that encapsulates the state and behaviour required for
 * inline text editing (for example, renaming an entity in place).
 *
 * @param isEditing Whether the field is currently in editing mode.
 * @param name The committed name that the editable value is derived from.
 * @param exitEditing Called whenever editing should stop.
 * @param validateName Returns a validation error string, or null when valid.
 * @param onNameSave Called with the new name when a valid change is saved.
 */
export function useEditableText(
  isEditing: boolean,
  name: string,
  exitEditing: () => void,
  validateName: (name: string) => string | null,
  onNameSave: (name: string) => void,
): UseEditableTextReturn {
  const inputRef = useRef<HTMLInputElement>(null);
  const [editableName, setEditableName] = useState(name);
  const [validationError, setValidationError] = useState<string | null>(null);
  const previousName = useRef(name);

  const validate = useCallback(
    (value: string) => {
      const nameError = validateName(value);

      setValidationError(nameError);

      return nameError;
    },
    [validateName],
  );

  const exitWithoutSaving = useCallback(() => {
    exitEditing();
    setEditableName(name);
    setValidationError(null);
  }, [exitEditing, name]);

  const attemptSave = useCallback(() => {
    const nameError = validate(editableName);

    if (editableName === name) {
      // No change detected, simply exit editing mode.
      exitWithoutSaving();
    } else if (nameError === null) {
      // A valid new name was entered, save it.
      exitEditing();
      onNameSave(editableName);
    } else {
      // The new name is invalid, exit and revert.
      exitWithoutSaving();
    }
  }, [editableName, exitEditing, exitWithoutSaving, name, onNameSave, validate]);

  const handleKeyUp = useCallback(
    (event: React.KeyboardEvent<HTMLInputElement>) => {
      if (event.key === "Enter") {
        attemptSave();
      } else if (event.key === "Escape") {
        exitWithoutSaving();
      }
    },
    [attemptSave, exitWithoutSaving],
  );

  const handleTitleChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const value = event.target.value;

      setEditableName(value);
      validate(value);
    },
    [validate],
  );

  // Save (or revert) when the input loses focus.
  useEffect(
    function attachFocusOutListener() {
      const input = inputRef.current;

      if (!input) return;

      const handleFocusOut = () => {
        attemptSave();
      };

      input.addEventListener("focusout", handleFocusOut);

      return () => {
        input.removeEventListener("focusout", handleFocusOut);
      };
    },
    [attemptSave, isEditing],
  );

  // Keep the editable value in sync when the committed name changes
  // externally while we are not editing.
  useEffect(
    function syncEditableName() {
      if (!isEditing && previousName.current !== name) {
        setEditableName(name);
      }

      previousName.current = name;
    },
    [isEditing, name],
  );

  return [
    inputRef,
    editableName,
    validationError,
    handleKeyUp,
    handleTitleChange,
  ];
}
